					if (labeled !== null) this._recordAiVerdict(videoId, labeled);
					this._aiLookupQueued.delete(videoId);
					if (labeled === null) this._aiLookupAttempts.set(videoId, AI_LABEL_LOOKUP_MAX_ATTEMPTS);
