			arrowSpan.className = 'ytkit-nav-arrow';
			arrowSpan.appendChild(ICONS.chevronRight());
			copyWrap.appendChild(labelSpan);
			copyWrap.appendChild(metaSpan);
			btn.appendChild(iconWrap);
