			estimateEl.textContent = t('ui_rydEstimateShort', 'est.');
			estimateEl.title = estimateCopy;
			estimateEl.setAttribute('aria-label', estimateCopy);
			dislikeButton.appendChild(estimateEl);
			_estimateEl = estimateEl;
